```js
function sweptCollides(ball, prev, brick) {
  const rx = brick.x - ball.r;
  const ry = brick.y - ball.r;
  const rw = brick.w + 2 * ball.r;
  const rh = brick.h + 2 * ball.r;
  // Liang-Barsky segment/AABB
  let t0 = 0, t1 = 1;
  const dx = ball.x - prev.x;
  const dy = ball.y - prev.y;
  const p = [-dx, dx, -dy, dy];
  const q = [prev.x - rx, rx + rw - prev.x, prev.y - ry, ry + rh - prev.y];
  for (let i = 0; i < 4; i++) {
    if (p[i] === 0) {
      if (q[i] < 0) return false; // parallel and outside
    } else {
      const t = q[i] / p[i];
      if (p[i] < 0) {
        if (t > t1) return false;
        if (t > t0) t0 = t;
      } else {
        if (t < t0) return false;
        if (t < t1) t1 = t;
      }
    }
  }
  return true;
}
```

