Now, the sweep function: I need it to handle the no-prev case. Let me write:

```js
export function sweptCollides(ball, brick) {
  const px = ball.px ?? ball.x;
  const py = ball.py ?? ball.y;
  const dx = ball.x - px;
  const dy = ball.y - py;
  if (dx === 0 && dy === 0) return collides(ball, brick);

  // Inflate the brick by the ball radius: the segment swept by the ball's
  // centre crosses the brick iff it crosses this enlarged rectangle.
  const x0 = brick.x - ball.r;
  const y0 = brick.y - ball.r;
  const x1 = brick.x + brick.w + ball.r;
  const y1 = brick.y + brick.h + ball.r;

  // Liang–Barsky clipping of the segment [P, P+D] against the rectangle.
  let t0 = 0;
  let t1 = 1;
  const p = [-dx, dx, -dy, dy];
  const q = [px - x0, x1 - px, py - y0, y1 - py];
  for (let i = 0; i < 4; i++) {
    if (p[i] === 0) {
      if (q[i] < 0) return false;
    } else {
      const t = q[i] / p[i];
      if (p[i] < 0) {
        if (t > t1) return false;
        if (t > t0) t0 = t;
      } else {
        if (t < t0) return false;
        if (t < t1) t1 = t;
      }
    }
  }
  return true;
}
```

