```js
export function bounceSwept(ball, brick) {
  const px = ball.px ?? ball.x;
  const py = ball.py ?? ball.y;

  if (py + ball.r <= brick.y) {
    // came from above → was moving down, now up
    ball.vy = -Math.abs(ball.vy);
    ball.y = brick.y - ball.r;
  } else if (py - ball.r >= brick.y + brick.h) {
    ball.vy = Math.abs(ball.vy);
    ball.y = brick.y + brick.h + ball.r;
  } else if (px + ball.r <= brick.x) {
    ball.vx = -Math.abs(ball.vx);
    ball.x = brick.x - ball.r;
  } else if (px - ball.r >= brick.x + brick.w) {
    ball.vx = Math.abs(ball.vx);
    ball.x = brick.x + brick.w + ball.r;
  } else {
    // Prev position also overlapped (unusual): fall back to the dominant axis.
    const overlapX = Math.min(ball.x + ball.r - brick.x, brick.x + brick.w - (ball.x - ball.r));
    const overlapY = Math.min(ball.y + ball.r - brick.y, brick.y + brick.h - (ball.y - ball.r));
    if (overlapX < overlapY) ball.vx = -ball.vx;
    else if (overlapY < overlapX) ball.vy = -ball.vy;
    else { ball.vx = -ball.vx; ball.vy = -ball.vy; }
  }
}
```

