// neon.test.js — PARTIAL coverage (on purpose).
//
// What is covered today: the collision primitives (`collides`, `sweptCollides`),
// the brick bounce (`bounceBall`, `brickHit` — ISSUES.md #1) and a couple of
// physics bounces. What is NOT covered yet: score and combo (see ISSUES.md #5),
// nor level progression. This is a starting point for the testing work ahead,
// not a complete suite.
//
// Run: `node --test "game/**/*.test.js"`  (or `npm test`)

import { test } from 'node:test';
import assert from 'node:assert/strict';

import {
  collides,
  sweptCollides,
  bounceBall,
  brickHit,
  step,
  makeBricks,
  createState,
  BRICK_ROWS,
  BRICK_COLS,
  WIDTH,
} from './neon.js';

