// a complete suite.
//
// Run: `node --test "game/**/*.test.js"`  (or `npm test`)

import { test } from 'node:test';
import assert from 'node:assert/strict';

import {
  collides,
  step,
  makeBricks,
  createState,
  BRICK_ROWS,
  BRICK_COLS,
  WIDTH,
} from './neon.js';

edits.newText:
test('makeBricks: full, all-alive grid at start', () => {
  const bricks = makeBricks(1);
  assert.equal(bricks.length, BRICK_ROWS * BRICK_COLS);
  assert.ok(bricks.every((b) => b.alive));
  assert.ok(bricks.every((b) => b.x >= 0 && b.x + b.w <= WIDTH));
});

// --- Brick bounce (ISSUES.md #1) -------------------------------------------

// NOTE: these tests exercise the penetration-depth fallback of bounceBall (the
// balls below have no previous position), i.e. the exact "smaller penetration"
// rule from ISSUES.md #1.

test('bounceBall: top face — vy flips, vx untouched, ball pushed out', () => {
  const ball = { x: 100, y: 96, r: 7, vx: 30, vy: 200 }; // moving down
  const brick = { x: 90, y: 100, w: 40, h: 20 };
  bounceBall(ball, brick);
  assert.equal(ball.vy, -200);
  assert.equal(ball.vx, 30);
  assert.equal(collides(ball, brick), false, 'ball must be pushed out of the brick');
});

test('bounceBall: bottom face — vy flips, vx untouched, ball pushed out', () => {
  const ball = { x: 100, y: 118, r: 7, vx: -30, vy: -200 }; // moving up
  const brick = { x: 90, y: 100, w: 40, h: 20 };
  bounceBall(ball, brick);
  assert.equal(ball.vy, 200);
  assert.equal(ball.vx, -30);
  assert.equal(collides(ball, brick), false);
});

test('bounceBall: side face — vx flips, vy untouched, ball pushed out', () => {
  const ball = { x: 85, y: 110, r: 7, vx: 200, vy: 30 }; // moving right
  const brick = { x: 90, y: 100, w: 40, h: 20 };
  bounceBall(ball, brick);
  assert.equal(ball.vx, -200);
  assert.equal(ball.vy, 30);
  assert.equal(collides(ball, brick), false);
});

test('bounceBall: corner — equal penetration flips both components', () => {
  // Ball centred exactly on the brick's top-left corner: penetration is equal
  // on both axes (7 px), so the hit is diagonal and both components flip.
  const ball = { x: 90, y: 100, r: 7, vx: 120, vy: -140 };
  const brick = { x: 90, y: 100, w: 40, h: 20 };
  bounceBall(ball, brick);
  assert.equal(ball.vx, -120);
  assert.equal(ball.vy, 140);
  assert.equal(collides(ball, brick), false);
});

test('bounceBall: approach direction decides the face (seam-safe)', () => {
  // A straight-up shot into the seam between two bricks: the previous position
  // (py) is below both bricks, so the ball bounces back down even though the
  // penetration heuristic alone would pick the side faces.
  const ball = { x: 134, y: 122.67, r: 7, px: 134, py: 127, vx: 0, vy: -260 };
  const brick = { x: 90, y: 100, w: 40, h: 20 };
  bounceBall(ball, brick);
  assert.equal(ball.vy, 260, 'vertical velocity should bounce back down');
  assert.equal(collides(ball, brick), false);
});

test('brickHit: a seam between two bricks bounces exactly once', () => {
  const a = { x: 90, y: 100, w: 40, h: 20, alive: true };
  const b = { x: 138, y: 100, w: 40, h: 20, alive: true };
  // Ball overlaps both bricks (it spans the 8 px gap), coming from below.
  const ball = { x: 134, y: 122.67, r: 7, px: 134, py: 127, vx: 0, vy: -260 };

  const hit = brickHit(ball, [a, b]);

  assert.ok(hit === a || hit === b, 'exactly one brick is hit');
  assert.equal(a.alive, hit !== a, 'the hit brick is destroyed');
  assert.equal(b.alive, hit !== b, 'the other brick survives');
  assert.equal(ball.vy, 260, 'the velocity is flipped exactly once');
  assert.equal(collides(ball, a) || collides(ball, b), false, 'ball pushed out');
});

test('sweptCollides: a fast ball that jumps over a brick is caught', () => {
  // Level 6: ballSpeed(6) = 710 px/s, worst-case dt = 50 ms → 35.5 px per
  // step, more than the 34 px (BRICK_H + 2 * BALL_R) needed to cross a brick.
  const ball = { x: 120, y: 227.5, r: 7, px: 120, py: 192, vx: 0, vy: 710 };
  const brick = { x: 100, y: 200, w: 40, h: 20 };
  assert.equal(collides(ball, brick), false, 'discrete check alone misses it');
  assert.equal(sweptCollides(ball, brick), true);
});

test('brickHit: a tunnelled ball bounces back off the top face', () => {
  const brick = { x: 100, y: 200, w: 40, h: 20, alive: true };
  const ball = { x: 120, y: 227.5, r: 7, px: 120, py: 192, vx: 0, vy: 710 };

  const hit = brickHit(ball, [brick]);

  assert.equal(hit, brick);
  assert.equal(brick.alive, false);
  assert.ok(ball.vy < 0, 'vertical velocity points back up');
  assert.ok(ball.y + ball.r <= brick.y, 'ball is parked above the brick');
});

